const items = $input.all();
const results = [];
for (const item of items) {
  const j = item.json;
  if (!j.position) continue;
  const salaryUsd = Number(j.salary_max || j.salary_min || 80000);
  const monthlyBrl = (salaryUsd / 12) * 5.60;
  let score = 60;
  let priority = 'NORMAL';
  if (monthlyBrl >= 35000) { score = 98; priority = 'CRITICAL_BUG'; }
  else if (monthlyBrl >= 20000) { score = 85; priority = 'HIGH'; }
  results.push({
    json: {
      category: 'remote_job',
      title: `${j.position} - ${j.company || 'Global Remote'}`,
      description: `Salário: US$ ${salaryUsd.toLocaleString()}/ano (~R$ ${monthlyBrl.toLocaleString('pt-BR', { maximumFractionDigits: 0 })}/mês) | Tags: ${(j.tags || []).slice(0, 4).join(', ')}`,
      opportunity_price: Number(monthlyBrl.toFixed(2)),
      original_price: Number(monthlyBrl.toFixed(2)),
      net_profit_estimate: Number(monthlyBrl.toFixed(2)),
      location: '100% Remoto Global',
      source_name: 'RemoteOK / LinkedIn',
      source_url: j.url || 'https://remoteok.com',
      evaluation_score: score,
      priority
    }
  });
}
return results.slice(0, 15);
